      ],
      networkRecords: [
        mockRequest({
          url: 'https://example.com/img.png',
          finished: true,
          statusCode: 200,
        }),
      ],
    });

    expect(elements).toEqual([mockElement({mimeType: 'image/png'})]);
  });
});

